// === Tab: mySketch ===
let myShader;
let hu = 0;

function setup() {
	createCanvas(1112, 834, WEBGL);
	colorMode(HSB, 255);
	noStroke();
	myShader = createShader(vert, frag);
	shader(myShader);
}

function draw() {
	background(20);
	directionalLight(hu%255, 200, 255, 0.5, 0.5, -1.0);
	ambientLight(100);

	myShader.setUniform('uTime', millis() / 1000.0);
	rotateY(millis() / 2000.0);
	icoSphere(220, 3);
	hu++;
}

function icoSphere(radius, detail) {
	const gId = `icoSphere|${detail}`;

	if (!this._renderer.geometryInHash(gId)) {
		const icoGeom = new p5.Geometry();

		const t = (1 + sqrt(5)) / 2;
		const vertices = [
			[- 1, t, 0], 	[1, t, 0], 	[- 1, - t, 0], 	[1, - t, 0],
			[0, - 1, t], 	[0, 1, t],	[0, - 1, - t], 	[0, 1, - t],
			[t, 0, - 1], 	[t, 0, 1], 	[- t, 0, - 1], 	[- t, 0, 1]
		];
		const indices = [
			[0, 11, 5], [0, 5, 1], 	[0, 1, 7], 	[0, 7, 10], [0, 10, 11],
			[1, 5, 9],  [5, 11, 4],	[11, 10, 2],[10, 7, 6],	[7, 1, 8],
			[3, 9, 4],  [3, 4, 2],	[3, 2, 6],	[3, 6, 8],	[3, 8, 9],
			[4, 9, 5],  [2, 4, 11],	[6, 2, 10],	[8, 6, 7],	[9, 8, 1]
		];

		let id = 0;
		for (let i = 0; i < indices.length; i++) {
			let v0 = new p5.Vector();
			v0.set(vertices[indices[i][0]]);

			let v1 = new p5.Vector();
			v1.set(vertices[indices[i][1]]);
			v1.sub(v0);

			let v2 = new p5.Vector();
			v2.set(vertices[indices[i][2]]);
			v2.sub(v0);

			for (let j = 0; j <= detail; j++) {
				// △
				for (let k = 0; k < j + 1; k++) {
					let s, t;
					let v, vv1, vv2;
					const r = random(1.0);
					const g = random(1.0);
					const b = random(1.0);

					// 頂点1
					s = k / (detail + 1);
					t = (j - k) / (detail + 1); 
					vv1 = p5.Vector.mult(v1, s);
					vv2 = p5.Vector.mult(v2, t);
					v = p5.Vector.add(vv1, vv2);
					v.add(v0);
					v.normalize();
					icoGeom.vertices.push(v.copy());
					icoGeom.vertexColors.push(r, g, b, 1.0);

					// 頂点2
					s = (k + 1) / (detail + 1);
					t = (j - k) / (detail + 1); 
					vv1 = p5.Vector.mult(v1, s);
					vv2 = p5.Vector.mult(v2, t);
					v = p5.Vector.add(vv1, vv2);
					v.add(v0);
					v.normalize();
					icoGeom.vertices.push(v.copy());
					icoGeom.vertexColors.push(r, g, b, 1.0);

					// 頂点3
					s = k / (detail + 1);
					t = (j + 1 - k) / (detail + 1); 
					vv1 = p5.Vector.mult(v1, s);
					vv2 = p5.Vector.mult(v2, t);
					v = p5.Vector.add(vv1, vv2);
					v.add(v0);
					v.normalize();
					icoGeom.vertices.push(v.copy());
					icoGeom.vertexColors.push(r, g, b, 1.0);

					// インデックス
					icoGeom.faces.push([id, id+1, id+2]);
					id += 3;
				}

				// ▽
				for (let k = 0; k < j; k++) {
					var s, t;
					var v, vv1, vv2;
					var r = random(1.0);
					var g = random(1.0);
					var b = random(1.0);

					// 頂点1
					s = k / (detail + 1);
					t = (j - k) / (detail + 1); 
					vv1 = p5.Vector.mult(v1, s);
					vv2 = p5.Vector.mult(v2, t);
					v = p5.Vector.add(vv1, vv2);
					v.add(v0);
					v.normalize();
					icoGeom.vertices.push(v.copy());
					icoGeom.vertexColors.push(r, g, b, 1.0);

					// 頂点2
					s = (k + 1) / (detail + 1);
					t = (j - k - 1) / (detail + 1); 
					vv1 = p5.Vector.mult(v1, s);
					vv2 = p5.Vector.mult(v2, t);
					v = p5.Vector.add(vv1, vv2);
					v.add(v0);
					v.normalize();
					icoGeom.vertices.push(v.copy());
					icoGeom.vertexColors.push(r, g, b, 1.0);

					// 頂点3
					s = (k + 1) / (detail + 1);
					t = (j - k) / (detail + 1); 
					vv1 = p5.Vector.mult(v1, s);
					vv2 = p5.Vector.mult(v2, t);
					v = p5.Vector.add(vv1, vv2);
					v.add(v0);
					v.normalize();
					icoGeom.vertices.push(v.copy());
					icoGeom.vertexColors.push(r, g, b, 1.0);

					// インデックス
					icoGeom.faces.push([id, id+1, id+2]);
					id += 3;
				}
			}
		}
		icoGeom.computeNormals();
		icoGeom._makeTriangleEdges()._edgesToVertices();

		// バッファ作成
		this._renderer.createBuffers(gId, icoGeom);
	}

	// 描画
	this._renderer.drawBuffersScaled(gId, radius, radius, radius);
}

