// === Tab: myShader ===
const vert = `
attribute vec3 aPosition;
attribute vec3 aNormal;
attribute vec4 aMaterialColor;

uniform float uTime;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

uniform vec3 uLightingDirection[5];
uniform vec3 uDirectionalDiffuseColors[5];
uniform vec3 uAmbientColor[5];

varying vec3 vDiffuseColor;

void main(void) {
	float amt = sin(uTime * aMaterialColor.r + aMaterialColor.g) * aMaterialColor.b;
  vec3 pos = aPosition + aNormal * amt * step(0.0, amt);
  vec4 viewModelPosition = uModelViewMatrix * vec4(pos, 1.0); 
  gl_Position = uProjectionMatrix * viewModelPosition;

  vec3 vertexNormal = normalize(uNormalMatrix * aNormal);
  vec3 lightDirection = normalize(-uLightingDirection[0]);
  float intensity = max(0.0, dot(lightDirection, vertexNormal));
  vDiffuseColor = uDirectionalDiffuseColors[0] * intensity;
  vDiffuseColor += uAmbientColor[0];
}
`;

const frag = `
precision highp float;

uniform vec4 uMaterialColor;

varying vec3 vDiffuseColor;

void main(void) {
  gl_FragColor = uMaterialColor;
	gl_FragColor.rgb *= vDiffuseColor;
}
`;

